import{z as i,x as s,o as r,c as p,q as A,j as n,D as t,d as a,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"前缀缓存与跨请求共享","description":"","frontmatter":{"title":"前缀缓存与跨请求共享","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-prefix-cache.md","filePath":"llm/kv-prefix-cache.md","lastUpdated":1791063341000}'),d={name:"llm/kv-prefix-cache.md"};function m(C,E,h,c,F,f){const l=s("Mermaid");return r(),p("div",null,[E[2]||(E[2]=A('<h1 id="前缀缓存与跨请求共享" tabindex="-1">前缀缓存与跨请求共享 <a class="header-anchor" href="#前缀缓存与跨请求共享" aria-label="Permalink to &quot;前缀缓存与跨请求共享&quot;">​</a></h1><div class="epigraph"><p>复用的单位不是请求，是前缀；共享省下的是第二次相同计算，前提是你能严格定义什么叫相同。</p><footer>—— 据 Kwon et al., SOSP 2023 的共享前缀与 copy-on-write；索引结构见 SGLang 的 RadixAttention</footer></div><p><a href="/llm/kv-paging-fragmentation">上一课</a>把池子管住了：水位线、按需分配、三种口径。但分配器只会一页一页地发，十个用户带着同一段系统提示到来，它就老老实实复制十份。共享是容量与延迟的第三根杠杆：不改每 token 字节（量化的事）、不删历史（驱逐的事），只把相同的计算付一次。本课写共享的簿记与正确性：什么算同一前缀、共享页挂在谁名下、命中与逐出怎么记账。前缀树的索引结构与多轮命中路径已各自写过，不重画；云侧计费口径也不在本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统提示、少样本示例、待问答的文档，在流量里高度重复。逐请求复制付三笔账：预填充的算力与 TTFT、KV 容量、以及调度上的排队时间。命中的定义是严的：从位置 0 起，<strong>chat 模板展开后的 token 序列</strong>逐个相同——不是用户可见文本相同。模板里注入的日期、随机种子、用户名，都会让序列在中途分叉，共享截止于第一个不同的 token；开头的可变项甚至能让 2K token 提示的共享量变成零。命中还有空间前提：请求必须落在持有该前缀的副本上，负载均衡若把同前缀请求打散到各卡，命中率在纸上再漂亮也是零。</p><p><span class="marginnote">术语翻译：chat 模板是把「多角色对话」拼成模型实际输入的那段代码——同一段话，模板不同，token 序列就可能不同。所以「用户看到的文本一样」不等于「模型吃的序列一样」，命中判定只认后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>缓存键</strong>。共享的第一件事是给页起一个可比较的名字：按页把 token 序列做成哈希链，父页哈希进子页，查最长命中即沿链走。键里必须带上影响 KV 数值的因子：精度（FP16 页与 INT8 页不是同一指纹，见 <a href="/llm/kv-int8-fp8">KV INT8/FP8</a>）、LoRA adapter（同前缀不同 adapter 的键值不同）。采样温度不进键——它不影响 KV，只影响输出。</p><p><span class="marginnote">直觉类比：哈希链像给接力赛每一棒记指纹——第 \\(k\\) 页的指纹由前 \\(k-1\\) 页的指纹和本页内容一起算出。查「这段提示存过没有」就是顺着指纹走，哪一棒对不上，共享就到哪棒为止；无法跳查中间，因为改一个 token，后面所有指纹全变。</span></p><p><strong>索引与命中</strong>。<a href="/llm/sglang-radix-tree">radix 树</a>把「已缓存的 token 序列」组织成可查最长前缀的结构；命中后请求的块表直接挂上共享页，引用计数加一——这正是第一课状态机的共享态，写时复制发生在生成首个新 token 的分叉处，共享段永远只到输入末尾。</p><p><strong>放置与逐出</strong>。命中依赖<a href="/llm/kv-aware-routing">缓存感知路由</a>把请求送到对的副本；共享页在无活跃请求引用时退化为纯缓存，按 LRU 逐出，判定必须与活跃引用解耦——缓存页可以丢，活跃页不能。</p>',11)),(r(),n(B,null,{default:t(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20HASH%5B%22%E6%A8%A1%E6%9D%BF%E5%B1%95%E5%BC%80%EF%BC%8C%E7%AE%97%20token%20%E5%93%88%E5%B8%8C%E9%93%BE%22%5D%0A%20%20HASH%20--%3E%20TREE%7B%22radix%20%E6%A0%91%E6%9F%A5%E6%9C%80%E9%95%BF%E5%91%BD%E4%B8%AD%22%7D%0A%20%20TREE%20--%3E%7C%E6%97%A0%7C%20PREFILL%5B%22%E5%85%A8%E9%87%8F%20prefill%EF%BC%8C%E9%A1%B5%E5%86%99%E5%85%A5%E5%B9%B6%E6%8C%82%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%7C%E9%83%A8%E5%88%86%7C%20INC%5B%22%E5%8F%AA%20prefill%20%E6%9C%AA%E5%91%BD%E4%B8%AD%E5%B0%BE%E5%B7%B4%22%5D%0A%20%20TREE%20--%3E%7C%E5%85%A8%E5%91%BD%E4%B8%AD%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%20prefill%22%5D%0A%20%20INC%20--%3E%20SHARE%5B%22%E5%9D%97%E8%A1%A8%E6%8C%82%E5%85%B1%E4%BA%AB%E9%A1%B5%EF%BC%8C%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%22%5D%0A%20%20SHARE%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E6%96%B0%20token%EF%BC%9ACoW%20%E5%87%BA%E6%96%B0%E9%A1%B5%22%5D%0A%20%20PREFILL%20--%3E%20GEN%0A%20%20GEN%20--%3E%20EV%7B%22%E7%BC%93%E5%AD%98%E9%A1%B5%E6%97%A0%E5%BC%95%E7%94%A8%3F%22%7D%0A%20%20EV%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22LRU%20%E9%80%90%E5%87%BA%EF%BC%8C%E9%A1%B5%E5%9B%9E%E6%B1%A0%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("共享改的是容量的期望值：\\(N\\) 条请求共享同一段提示时，提示段从 \\(N\\cdot\\mathrm{KV}(n_p)\\) 塌缩成 \\(\\mathrm{KV}(n_p)\\)，生成段仍按请求各付各的（多样本公式见 "),e("a",{href:"/llm/kv-cache-size-math"},"KV 大小计算"),a("）。它省的时间全在 TTFT——预填充少算或不算；decode 每步仍要扫全部可见 KV，带宽一步没省，别把 TTFT 收益写进 TPOT。正确性由 copy-on-write 保证：共享页只读，任何写入（包括投机解码的草稿回滚）先复制，这就是第一课「写权只属唯一引用者」在共享场景的兑现。")],-1)),E[5]||(E[5]=e("p",null,[a("命中率的统计口径决定这套机制可不可信：分母应是"),e("strong",null,"可命中请求"),a("（携带长共享前缀的请求），而不是全部请求。一个以随机对话为主的站点，前缀缓存命中率天然低，不代表实现坏了；反之，把「命中页数 / 总页数」当命中率，一份被千次引用的系统提示页会把数字撑到虚高。")],-1)),(r(),n(B,null,{default:t(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E5%85%B1%E4%BA%AB%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%3A%204K%20token%22%5D%20--%3E%20ONE%5B%22%E7%89%A9%E7%90%86%E5%8F%AA%E5%AD%98%E4%B8%80%E4%BB%BD%20KV%22%5D%0A%20%20ONE%20--%3E%20RA%5B%22%E8%AF%B7%E6%B1%82%20A%3A%20%E7%94%9F%E6%88%90%E6%AE%B5%202K%22%5D%0A%20%20ONE%20--%3E%20RB%5B%22%E8%AF%B7%E6%B1%82%20B%3A%20%E7%94%9F%E6%88%90%E6%AE%B5%202K%22%5D%0A%20%20ONE%20--%3E%20RC%5B%22%E8%AF%B7%E6%B1%82%20C%3A%20%E7%94%9F%E6%88%90%E6%AE%B5%202K%22%5D%0A%20%20RA%20--%3E%20ACC%5B%22%E5%AE%B9%E9%87%8F%20%3D%204K%20%2B%203%20x%202K%2C%20%E8%80%8C%E4%B8%8D%E6%98%AF%203%20x%206K%22%5D%0A%20%20RB%20--%3E%20ACC%0A%20%20RC%20--%3E%20ACC%0A%20%20ACC%20--%3E%20W%5B%22%E7%9C%81%E7%9A%84%E6%98%AF%20prefill%20%E7%AE%97%E5%8A%9B%E4%B8%8E%20TTFT%3B%20decode%20%E6%AF%8F%E6%AD%A5%E4%BB%8D%E8%A6%81%E6%89%AB%E5%85%A8%E9%83%A8%E5%8F%AF%E8%A7%81%20KV%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">把日期、随机 ID 之类可变内容注入提示开头，是最常见的自伤：命中在第一个不同 token 处截止，后面的 1999 个 token 白算。可变部分挪到提示末尾，固定前缀的共享就能延续。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>语义相似不命中：换一个说法的同一份文档在页表眼里是全新序列，模糊复用是检索或 <a href="/llm/prompt-cache">Prompt Cache</a> 模块拼接的事。非前缀的重复块（多文档拼接）在自动前缀共享下只有第一块命中，<a href="/llm/lmcache">LMCache</a> 一类方案处理的是这个问题。多轮对话要靠严格的「前缀加长」才命中，助手历史必须进索引（见<a href="/llm/multi-turn-prefix">多轮前缀命中</a>）。最后，共享与量化互相牵制：改精度等于改指纹，滚动升级模型或 adapter 时，旧键的页要成批失效，否则命中到过期数值。</p><p><span class="marginnote">数字实例：滚动升级把精度从 FP16 换成 INT8 后，旧 FP16 页的指纹全部过期——不清掉就会命中「同名不同值」的页，输出静默漂移；全清则命中率从八成掉回零，等新精度的页重新积累。升级窗口要按这本账排期。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享的对象是从位置 0 起逐 token 相同的前缀，判定发生在模板展开后的 token 上。</li><li>缓存键带精度与 adapter，不带采样参数；radix 树查最长命中，引用计数管共享。</li><li>收益在 TTFT 与容量期望值，不在 decode 带宽；生成段仍按请求各付。</li><li>CoW 保证共享页只读；逐出只针对无引用的缓存页，与活跃集解耦。</li><li>命中率的分母是可命中请求；放置（路由）决定命中的下限。</li><li>出处：Kwon et al., SOSP 2023；Zheng et al., SGLang/RadixAttention, NeurIPS 2024；据本仓库既有课程整理。</li></ul>',6))])}const k=i(d,[["render",m]]);export{D as __pageData,k as default};
